'@ | ConvertFrom-Csv -Delimiter '|'

$byId = @{}
foreach ($proposal in $proposalText) { $byId[$proposal.ID] = $proposal }
if ($matrix.Count -ne 46 -or $byId.Count -ne 46) { throw 'Expected exactly 46 requirements and 46 proposal records.' }

foreach ($row in $matrix) {
    $proposal = $byId[$row.ID]
    if ($null -eq $proposal) { throw "Missing proposal for $($row.ID)" }
    $row.Dependency = $proposal.Dependency
    $row | Add-Member -Force -NotePropertyName PriorityProposal -NotePropertyValue $proposal.Priority
    $row | Add-Member -Force -NotePropertyName PriorityBasis -NotePropertyValue $proposal.Basis
    $row | Add-Member -Force -NotePropertyName AcceptanceCheck -NotePropertyValue $proposal.Acceptance
    $row | Add-Member -Force -NotePropertyName VerificationPlan -NotePropertyValue $proposal.Verification
    if ($row.ID -eq 'DOCK-027') { $row.OfficialAppleReferences = 'A1;A13' }
    if ($row.ID -in @('DOCK-028', 'DOCK-029')) { $row.OfficialAppleReferences = 'A14' }
}

# Evidence audit and narrow corrections from the complete 46-row review.
# The original IDs, requirement text, class, and phase columns are intentionally untouched.
$auditText = @'
ID|Status|Review
DOCK-001|DIRECT SEMANTICS|A1/A2 document bottom, left, and right placement; exact spacing, zone geometry, and orientation details require Mac sampling; Windows layout remains a product proposal.
DOCK-002|DIRECT SEMANTICS|A2 documents a size control; neither A2 nor A15 establishes this product's numeric size bounds or pixel dimensions; those remain unmeasured.
DOCK-003|DESIGN GUIDANCE ONLY|A4 concerns app icon layers and A11 describes system materials; neither specifies the Dock baseplate blur, opacity, edge, shadow, or optical parameters.
DOCK-004|DIRECT SEMANTICS|A2 documents magnification as a setting; it does not specify the response curve, neighbor radius, maximum scale, or timing.
DOCK-005|PARTIAL|A4 provides layered app-icon design guidance; A6 is an IP/trademark review entry, not a Dock asset specification or authorization for assets.
DOCK-006|DIRECT SEMANTICS|A1 documents adding an item by drag and placing an alias; Windows shortcut identity, duplicate rules, and feedback are product design.
DOCK-007|DIRECT SEMANTICS|A1 explicitly says removing the Dock item removes only its alias and leaves the original item; Windows persistence behavior still requires implementation tests.
DOCK-008|DIRECT SEMANTICS|A1 documents dragging an item to rearrange it; atomic persistence, cancellation, and restart behavior are Windows acceptance proposals.
DOCK-009|DIRECT SEMANTICS|A1 documents up to three recently used apps not already in Dock and A2 has a visibility setting; Windows history source, retention, and default remain owner decisions.
DOCK-010|DIRECT SEMANTICS|A2/A10 document an indicator for open apps; Windows app/window identity matching and unknown-state treatment are product implementation requirements.
DOCK-011|DIRECT SEMANTICS|A1/A2 document opening-app bounce and a setting; neither gives a curve, duration, nor a reliable Windows launch-completion signal.
DOCK-012|DIRECT SEMANTICS|A1 documents clicking an app icon to open it; Windows launch adapters and error reporting are product implementation requirements.
DOCK-013|PARTIAL|A1 documents opening an app from its Dock icon, but not Windows foreground policy, HWND selection, or non-activating window behavior.
DOCK-014|HIG GUIDANCE ONLY|A5 describes Dock-menu guidance and possible window-related commands; it is not a guarantee that every Mac app exposes a chooser or defines its ordering.
DOCK-015|DIRECT SEMANTICS|A1 documents a Control-click shortcut menu; applicable Windows commands and UI Automation access remain product design.
DOCK-016|HIG GUIDANCE ONLY|A5 recommends system and app-provided Dock menu commands; support and command availability vary by app and do not imply a universal provider API.
DOCK-017|DIRECT SEMANTICS|A1 documents Option-click switching to the previous app and hiding the current app; a Windows modifier mapping is a product proposal, not native Windows behavior.
DOCK-018|DIRECT SEMANTICS|A1 documents Option-Command-click switching to one app and hiding others; Windows scope, integrity boundaries, and opt-in policy are product proposals.
DOCK-019|DIRECT SEMANTICS|A1 documents Command-click to show an item in Finder; Explorer selection is a Windows role mapping, not an Apple behavior claim.
DOCK-020|DIRECT SEMANTICS|A1 documents dragging a file to an app icon to open it; Windows OLE/Shell delivery and source-file preservation require implementation validation.
DOCK-021|SOURCE GAP|A1 uses Finder as an example of an app opened from Dock but does not establish Finder as a universal or default pinned item; Explorer pinning is an owner decision and Windows proposal.
DOCK-022|DIRECT SEMANTICS|A1 describes app/file placement on opposite sides of Dock separators; exact side/axis geometry for every orientation requires Mac sampling.
DOCK-023|DIRECT SEMANTICS|A1/A3 document Downloads as a Dock folder role; Windows Known Folder resolution and redirection handling are product mapping.
DOCK-024|DIRECT SEMANTICS|A3 documents Folder and Stack presentation; Windows representation persistence and filesystem safety are product requirements.
DOCK-025|DIRECT SEMANTICS|A3 explicitly lists Fan, Grid, and List; a fallback does not satisfy this original requirement and must be reported as a gap.
DOCK-026|DIRECT SEMANTICS|A3 documents sorting choices including name, date added, and date created; deterministic tie-breaks and inaccessible metadata behavior are not specified there.
DOCK-027|PARTIAL|A1 identifies the Bin as a Dock item and A13 lists empty/full AppKit image names; these do not prove Dock status-transition timing or appearance.
DOCK-028|DIRECT SEMANTICS|A14 supports Mac Trash opening/recovery and destructive-emptying semantics; Windows Recycle Bin commands and confirmation UI are a platform mapping.
DOCK-029|DIRECT SEMANTICS|A14 supports moving deleted files to Mac Trash and the recoverability boundary; the Windows Shell recycle operation is a separate implementation requirement.
DOCK-030|DIRECT SEMANTICS|A2 documents the option to minimize a window into its app icon; Windows window association and persistence are not specified by Apple.
DOCK-031|DIRECT SEMANTICS|A2 documents the alternate minimized-window area when the app-icon option is off; Windows live-window proxy behavior still requires implementation.
DOCK-032|DIRECT SEMANTICS|A2 documents a minimize-effect setting and A15 lists Genie/Scale configuration values; neither defines animation curves, optical output, or Windows interception capability.
DOCK-033|DIRECT SEMANTICS|A2 documents automatic hiding and edge reveal; Windows edge detection, menu holds, recovery, and fullscreen suppression are product/system-integration requirements.
DOCK-034|DIRECT SEMANTICS|A2 documents a control for opening-app animation; reduced-motion integration and behavior on Windows remain product design.
DOCK-035|DIRECT SEMANTICS|A2 documents a control for open-app indicators; the underlying Windows tracker state must remain independent by design.
DOCK-036|DIRECT SEMANTICS|A2 documents showing suggested/recent apps; Windows history collection, retention, deletion, and default state are not specified.
DOCK-037|PARTIAL|A1 documents entering and navigating Dock by keyboard and activating an item; Windows UI Automation roles, names, and screen-reader behavior are not covered by Apple sources.
DOCK-038|DIRECT SEMANTICS|A1/A8 document Dock badges and notification badge controls; Windows badge values require a trusted authorized provider.
